import { styled, View } from '@tamagui/web';
import type { AllHTMLAttributes, RefAttributes } from 'react';

import { prependClassName } from '../../helpers/prependClassName';

export type MessageProps = AllHTMLAttributes<HTMLDivElement> &
	RefAttributes<HTMLDivElement> & {
		clickable?: boolean;
		sequential?: boolean;
		className?: string;
		isSelected?: boolean;
		isEditing?: boolean;
		isPending?: boolean;
		highlight?: boolean;
	};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const MessageFrame = styled(View, {
	render: 'div',
	position: 'relative',
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'flex-start',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	boxSizing: 'content-box',
	marginInline: '2px',
	paddingBlockEnd: '4px',
	paddingInline: '20px',
	borderWidth: '1px',
	borderStyle: 'solid',
	borderColor: {
		'default': 'transparent',
		'focus-visible': 'var(--rcx-color-stroke-highlight, #156ff5)',
	},
	borderRadius: {
		'focus-visible': 'var(--rcx-border-radius-medium, 0.25rem)',
	},
	outlineStyle: 'none',
	boxShadow: {
		'focus-visible': '0 0 0 2px var(--rcx-color-stroke-extra-light-highlight, #d1ebfe)',
	},
	variants: {
		tone: {
			default: {
				backgroundColor: {
					hover: 'var(--rcx-message-background-color-hover, var(--rcx-color-surface-hover, #f2f3f5))',
				},
			},
			selected: {
				backgroundColor: 'var(--rcx-message-background-color-selected, var(--rcx-color-surface-selected, #d7dbe0))',
			},
			editing: {
				color: 'var(--rcx-message-background-color-editing, var(--rcx-color-status-font-on-warning-2, #2f343d))',
				backgroundColor: 'var(--rcx-message-background-color-editing, var(--rcx-color-status-background-warning-2, #fff8e0))',
			},
		},
		rhythm: {
			sequential: {
				paddingBlockStart: '4px',
			},
			regular: {
				paddingBlockStart: '8px',
			},
		},
		clickable: {
			true: {
				cursor: 'pointer',
			},
			false: {},
		},
	},
});

// end of generated

function Message({ className, children, clickable, sequential, isSelected, isEditing, isPending, highlight, ...props }: MessageProps) {
	const isClickable = Boolean(clickable || props.onClick);

	return (
		<MessageFrame
			render={<div {...props} />}
			tone={(isEditing && 'editing') || (isSelected && 'selected') || 'default'}
			rhythm={sequential ? 'sequential' : 'regular'}
			clickable={isClickable}
			className={prependClassName(
				className,
				[
					'rcx-message',
					isClickable && 'rcx-message--clickable',
					sequential && 'rcx-message--sequential',
					isSelected && 'rcx-message--selected',
					isEditing && 'rcx-message--editing',
					isPending && 'rcx-message--pending',
					highlight && 'rcx-message--highlight',
				]
					.filter(Boolean)
					.join(' '),
			)}
		>
			{children}
		</MessageFrame>
	);
}

export default Message;
